pub const C05_PLAN_SIGNATURE: u64 = 0xcae02cd91aaabbf9;
type C05N0Static = StaticBitPack<8, 6, 128, 96>;
#[inline(always)]
fn c05_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(8), row, 6, 128, 96)?)))
}

#[inline(always)]
fn c05_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(8), Span::new(start, end)?, 6, 128, 96)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C05N1Static = StaticDelta<7, 256, false, C05N0Static>;
#[inline(always)]
fn c05_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let block = row / 256;
    let block_start = block * 256;
    let mut value = i128::from(session.read_i64(FieldId(7), block)?);
    if block_start < row { c05_n0_visit(session, block_start + 1, row + 1, &mut |_session, code, start, end| {
        let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
        let delta = i128::from(unzigzag(code));
        for _ in start..end { value = value.checked_add(delta).ok_or("generated delta overflow")?; } Ok(())
    })?; }
    Ok(Some(value))
}

#[inline(always)]
fn c05_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut block_start = start / 256 * 256;
    while block_start < end {
        let block_end = (block_start + 256).min(end);
        let emit_start = start.max(block_start);
        let mut value = i128::from(session.read_i64(FieldId(7), block_start / 256)?);
        if block_start >= emit_start { visitor(session, Some(value), block_start, block_start + 1)?; }
        if block_start + 1 < block_end { c05_n0_visit(session, block_start + 1, block_end, &mut |session, code, span_start, span_end| {
            let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
            let delta = i128::from(unzigzag(code));
            for row in span_start..span_end { value = value.checked_add(delta).ok_or("generated delta span overflow")?; if row >= emit_start { visitor(session, Some(value), row, row + 1)?; } } Ok(())
        })?; }
        block_start += 256;
    }
    Ok(())
}

type C05N2Static = StaticFor<6, C05N1Static>;
#[inline(always)]
fn c05_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(6), 0)?);
    match c05_n1_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

#[inline(always)]
fn c05_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let base = i128::from(session.read_i64(FieldId(6), 0)?);
    c05_n1_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let value = value.map(|value| value.checked_add(base).ok_or("generated FOR span overflow")).transpose()?;
        visitor(session, value, span_start, span_end)
    })
}

type C05N3Static = StaticPatch<3, 4, 5, 15, 32, C05N2Static>;
#[inline(always)]
fn c05_n3_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match find_position(session, FieldId(4), FieldId(3), 15, 32, row)? {
        Some(exception) => Ok(Some(i128::from(session.read_i64(FieldId(5), exception)?))),
        None => c05_n2_get(session, row),
    }
}

#[inline(always)]
fn c05_n3_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut exception = lower_bound_position(session, FieldId(4), FieldId(3), 15, 32, start)?;
    let mut patches = Vec::new();
    while exception < 15 { let row = session.read_u32(FieldId(3), exception)? as usize; if row >= end { break; } patches.push((row, i128::from(session.read_i64(FieldId(5), exception)?))); exception += 1; }
    let mut patch = 0;
    c05_n2_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let mut cursor = span_start; while patch < patches.len() && patches[patch].0 < span_end { let (row, exception) = patches[patch]; if row < cursor { return Err("generated patch positions are not ordered".into()); }
        if cursor < row { visitor(session, value, cursor, row)?; } visitor(session, Some(exception), row, row + 1)?; cursor = row + 1; patch += 1; }
        if cursor < span_end { visitor(session, value, cursor, span_end)?; } Ok(())
    })
}

type C05N4Static = StaticNullable<1, 2, 256, C05N3Static>;
#[inline(always)]
fn c05_n4_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match nullable_rank(session, FieldId(1), FieldId(2), row, 256)? {
        Some(compact_row) => c05_n3_get(session, compact_row),
        None => Ok(None),
    }
}

#[inline(always)]
fn c05_n4_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut logical = start; let mut compact = nullable_prefix_rank(session, FieldId(1), FieldId(2), start, 256)?;
    while logical < end { let valid = nullable_is_valid(session, FieldId(1), logical)?; let run_start = logical; logical += 1; while logical < end && nullable_is_valid(session, FieldId(1), logical)? == valid { logical += 1; }
        if valid { let child_start = compact; compact += logical - run_start; c05_n3_visit(session, child_start, compact, &mut |session, value, span_start, span_end| { let mapped_start = run_start + span_start - child_start; visitor(session, value, mapped_start, mapped_start + span_end - span_start) })?; } else { visitor(session, None, run_start, logical)?; }
    } Ok(())
}

