pub const C08_PLAN_SIGNATURE: u64 = 0x1c2d25c6c2797877;
type C08N0Static = StaticBitPack<6, 6, 128, 96>;
#[inline(always)]
fn c08_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(6), row, 6, 128, 96)?)))
}

#[inline(always)]
fn c08_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(6), Span::new(start, end)?, 6, 128, 96)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C08N1Static = StaticDelta<5, 256, false, C08N0Static>;
#[inline(always)]
fn c08_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let block = row / 256;
    let block_start = block * 256;
    let mut value = i128::from(session.read_i64(FieldId(5), block)?);
    if block_start < row { c08_n0_visit(session, block_start + 1, row + 1, &mut |_session, code, start, end| {
        let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
        let delta = i128::from(unzigzag(code));
        for _ in start..end { value = value.checked_add(delta).ok_or("generated delta overflow")?; } Ok(())
    })?; }
    Ok(Some(value))
}

#[inline(always)]
fn c08_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut block_start = start / 256 * 256;
    while block_start < end {
        let block_end = (block_start + 256).min(end);
        let emit_start = start.max(block_start);
        let mut value = i128::from(session.read_i64(FieldId(5), block_start / 256)?);
        if block_start >= emit_start { visitor(session, Some(value), block_start, block_start + 1)?; }
        if block_start + 1 < block_end { c08_n0_visit(session, block_start + 1, block_end, &mut |session, code, span_start, span_end| {
            let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
            let delta = i128::from(unzigzag(code));
            for row in span_start..span_end { value = value.checked_add(delta).ok_or("generated delta span overflow")?; if row >= emit_start { visitor(session, Some(value), row, row + 1)?; } } Ok(())
        })?; }
        block_start += 256;
    }
    Ok(())
}

type C08N2Static = StaticFor<4, C08N1Static>;
#[inline(always)]
fn c08_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(4), 0)?);
    match c08_n1_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

#[inline(always)]
fn c08_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let base = i128::from(session.read_i64(FieldId(4), 0)?);
    c08_n1_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let value = value.map(|value| value.checked_add(base).ok_or("generated FOR span overflow")).transpose()?;
        visitor(session, value, span_start, span_end)
    })
}

type C08N3Static = StaticPatch<1, 2, 3, 16, 32, C08N2Static>;
#[inline(always)]
fn c08_n3_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match find_position(session, FieldId(2), FieldId(1), 16, 32, row)? {
        Some(exception) => Ok(Some(i128::from(session.read_i64(FieldId(3), exception)?))),
        None => c08_n2_get(session, row),
    }
}

#[inline(always)]
fn c08_n3_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut exception = lower_bound_position(session, FieldId(2), FieldId(1), 16, 32, start)?;
    let mut patches = Vec::new();
    while exception < 16 { let row = session.read_u32(FieldId(1), exception)? as usize; if row >= end { break; } patches.push((row, i128::from(session.read_i64(FieldId(3), exception)?))); exception += 1; }
    let mut patch = 0;
    c08_n2_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let mut cursor = span_start; while patch < patches.len() && patches[patch].0 < span_end { let (row, exception) = patches[patch]; if row < cursor { return Err("generated patch positions are not ordered".into()); }
        if cursor < row { visitor(session, value, cursor, row)?; } visitor(session, Some(exception), row, row + 1)?; cursor = row + 1; patch += 1; }
        if cursor < span_end { visitor(session, value, cursor, span_end)?; } Ok(())
    })
}

