pub const C11_PLAN_SIGNATURE: u64 = 0x235045b35417301b;
type C11N0Static = StaticBitPack<5, 17, 128, 272>;
#[inline(always)]
fn c11_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(5), row, 17, 128, 272)?)))
}

#[inline(always)]
fn c11_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(5), Span::new(start, end)?, 17, 128, 272)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C11N1Static = StaticFor<4, C11N0Static>;
#[inline(always)]
fn c11_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let base = i128::from(session.read_i64(FieldId(4), 0)?);
    match c11_n0_get(session, row)? {
        Some(value) => Ok(Some(value.checked_add(base).ok_or("generated FOR overflow")?)),
        None => Ok(None),
    }
}

#[inline(always)]
fn c11_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let base = i128::from(session.read_i64(FieldId(4), 0)?);
    c11_n0_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let value = value.map(|value| value.checked_add(base).ok_or("generated FOR span overflow")).transpose()?;
        visitor(session, value, span_start, span_end)
    })
}

type C11N2Static = StaticPatch<1, 2, 3, 16, 32, C11N1Static>;
#[inline(always)]
fn c11_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match find_position(session, FieldId(2), FieldId(1), 16, 32, row)? {
        Some(exception) => Ok(Some(i128::from(session.read_i64(FieldId(3), exception)?))),
        None => c11_n1_get(session, row),
    }
}

#[inline(always)]
fn c11_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut exception = lower_bound_position(session, FieldId(2), FieldId(1), 16, 32, start)?;
    let mut patches = Vec::new();
    while exception < 16 { let row = session.read_u32(FieldId(1), exception)? as usize; if row >= end { break; } patches.push((row, i128::from(session.read_i64(FieldId(3), exception)?))); exception += 1; }
    let mut patch = 0;
    c11_n1_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let mut cursor = span_start; while patch < patches.len() && patches[patch].0 < span_end { let (row, exception) = patches[patch]; if row < cursor { return Err("generated patch positions are not ordered".into()); }
        if cursor < row { visitor(session, value, cursor, row)?; } visitor(session, Some(exception), row, row + 1)?; cursor = row + 1; patch += 1; }
        if cursor < span_end { visitor(session, value, cursor, span_end)?; } Ok(())
    })
}

