type C12N0Static = StaticBitPack<7, 2, 128, 32>;
#[inline(always)]
fn c12_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(7), row, 2, 128, 32)?)))
}

type C12N1Static = StaticRle<5, 6, 443, 32, C12N0Static>;
#[inline(always)]
fn c12_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let (run, _, _) = locate_indexed(session, FieldId(6), FieldId(5), 443, 32, row)?;
    c12_n0_get(session, run)
}

#[inline(always)]
fn c12_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    if start == end { return Ok(()); }
    let (mut run, mut run_start, _) = locate_indexed(session, FieldId(6), FieldId(5), 443, 32, start)?;
    while run < 443 && run_start < end {
        let run_end = run_start.checked_add(session.read_u32(FieldId(5), run)? as usize).ok_or("generated RLE row overflow")?;
        let span_start = start.max(run_start);
        let span_end = end.min(run_end);
        if span_start < span_end { let value = c12_n0_get(session, run)?; visitor(session, value, span_start, span_end)?; }
        run_start = run_end; run += 1;
    }
    Ok(())
}

type C12N2Static = StaticDictionary<4, 3, C12N1Static>;
#[inline(always)]
fn c12_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let id = usize::try_from(c12_n1_get(session, row)?.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
    if id >= 3 { return Err("generated dictionary id is outside table".into()); }
    Ok(Some(i128::from(session.read_i64(FieldId(4), id)?)))
}

#[inline(always)]
fn c12_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    c12_n1_visit(session, start, end, &mut |session, id, span_start, span_end| {
        let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
        if id >= 3 { return Err("generated dictionary id is outside table".into()); }
        let value = Some(i128::from(session.read_i64(FieldId(4), id)?)); visitor(session, value, span_start, span_end)
    })
}

type C12N3Static = StaticPatch<1, 2, 3, 16, 32, C12N2Static>;
#[inline(always)]
fn c12_n3_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match find_position(session, FieldId(2), FieldId(1), 16, 32, row)? {
        Some(exception) => Ok(Some(i128::from(session.read_i64(FieldId(3), exception)?))),
        None => c12_n2_get(session, row),
    }
}

#[inline(always)]
fn c12_n3_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut exception = lower_bound_position(session, FieldId(2), FieldId(1), 16, 32, start)?;
    let mut patches = Vec::new();
    while exception < 16 { let row = session.read_u32(FieldId(1), exception)? as usize; if row >= end { break; } patches.push((row, i128::from(session.read_i64(FieldId(3), exception)?))); exception += 1; }
    let mut patch = 0;
    c12_n2_visit(session, start, end, &mut |session, value, span_start, span_end| {
        let mut cursor = span_start; while patch < patches.len() && patches[patch].0 < span_end { let (row, exception) = patches[patch]; if row < cursor { return Err("generated patch positions are not ordered".into()); }
        if cursor < row { visitor(session, value, cursor, row)?; } visitor(session, Some(exception), row, row + 1)?; cursor = row + 1; patch += 1; }
        if cursor < span_end { visitor(session, value, cursor, span_end)?; } Ok(())
    })
}

