pub const C15_PLAN_SIGNATURE: u64 = 0x9c10e0dadb6e307c;
type C15N0Static = StaticBitPack<4, 4, 128, 64>;
#[inline(always)]
fn c15_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(4), row, 4, 128, 64)?)))
}

#[inline(always)]
fn c15_n0_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let values = session.read_bit_values(FieldId(4), Span::new(start, end)?, 4, 128, 64)?;
    for (offset, value) in values.into_iter().enumerate() { let row = start + offset; visitor(session, Some(i128::from(value)), row, row + 1)?; }
    Ok(())
}

type C15N1Static = StaticDelta<3, 256, true, C15N0Static>;
#[inline(always)]
fn c15_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let block = row / 256;
    let block_start = block * 256;
    let mut value = i128::from(session.read_i64(FieldId(3), block)?);
    if block_start < row { c15_n0_visit(session, block_start + 1, row + 1, &mut |_session, code, start, end| {
        let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
        let delta = i128::from(code);
        for _ in start..end { value = value.checked_add(delta).ok_or("generated delta overflow")?; } Ok(())
    })?; }
    Ok(Some(value))
}

#[inline(always)]
fn c15_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut block_start = start / 256 * 256;
    while block_start < end {
        let block_end = (block_start + 256).min(end);
        let emit_start = start.max(block_start);
        let mut value = i128::from(session.read_i64(FieldId(3), block_start / 256)?);
        if block_start >= emit_start { visitor(session, Some(value), block_start, block_start + 1)?; }
        if block_start + 1 < block_end { c15_n0_visit(session, block_start + 1, block_end, &mut |session, code, span_start, span_end| {
            let code = u64::try_from(code.ok_or("generated delta code is null")?).map_err(|_| "generated delta code does not fit u64")?;
            let delta = i128::from(code);
            for row in span_start..span_end { value = value.checked_add(delta).ok_or("generated delta span overflow")?; if row >= emit_start { visitor(session, Some(value), row, row + 1)?; } } Ok(())
        })?; }
        block_start += 256;
    }
    Ok(())
}

type C15N2Static = StaticNullable<1, 2, 256, C15N1Static>;
#[inline(always)]
fn c15_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    match nullable_rank(session, FieldId(1), FieldId(2), row, 256)? {
        Some(compact_row) => c15_n1_get(session, compact_row),
        None => Ok(None),
    }
}

#[inline(always)]
fn c15_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    let mut logical = start; let mut compact = nullable_prefix_rank(session, FieldId(1), FieldId(2), start, 256)?;
    while logical < end { let valid = nullable_is_valid(session, FieldId(1), logical)?; let run_start = logical; logical += 1; while logical < end && nullable_is_valid(session, FieldId(1), logical)? == valid { logical += 1; }
        if valid { let child_start = compact; compact += logical - run_start; c15_n1_visit(session, child_start, compact, &mut |session, value, span_start, span_end| { let mapped_start = run_start + span_start - child_start; visitor(session, value, mapped_start, mapped_start + span_end - span_start) })?; } else { visitor(session, None, run_start, logical)?; }
    } Ok(())
}

