pub const C17_PLAN_SIGNATURE: u64 = 0x7f3a62454dd48606;
type C17N0Static = StaticBitPack<4, 10, 128, 160>;
#[inline(always)]
fn c17_n0_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    Ok(Some(i128::from(session.read_bits(FieldId(4), row, 10, 128, 160)?)))
}

type C17N1Static = StaticRle<2, 3, 2048, 32, C17N0Static>;
#[inline(always)]
fn c17_n1_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let (run, _, _) = locate_indexed(session, FieldId(3), FieldId(2), 2048, 32, row)?;
    c17_n0_get(session, run)
}

#[inline(always)]
fn c17_n1_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    if start == end { return Ok(()); }
    let (mut run, mut run_start, _) = locate_indexed(session, FieldId(3), FieldId(2), 2048, 32, start)?;
    while run < 2048 && run_start < end {
        let run_end = run_start.checked_add(session.read_u32(FieldId(2), run)? as usize).ok_or("generated RLE row overflow")?;
        let span_start = start.max(run_start);
        let span_end = end.min(run_end);
        if span_start < span_end { let value = c17_n0_get(session, run)?; visitor(session, value, span_start, span_end)?; }
        run_start = run_end; run += 1;
    }
    Ok(())
}

type C17N2Static = StaticDictionary<1, 1024, C17N1Static>;
#[inline(always)]
fn c17_n2_get(session: &mut ReadSession<'_>, row: usize) -> Result<Option<i128>, String> {
    let id = usize::try_from(c17_n1_get(session, row)?.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
    if id >= 1024 { return Err("generated dictionary id is outside table".into()); }
    Ok(Some(i128::from(session.read_i64(FieldId(1), id)?)))
}

#[inline(always)]
fn c17_n2_visit<F>(session: &mut ReadSession<'_>, start: usize, end: usize, visitor: &mut F) -> Result<(), String> where F: FnMut(&mut ReadSession<'_>, Option<i128>, usize, usize) -> Result<(), String> {
    c17_n1_visit(session, start, end, &mut |session, id, span_start, span_end| {
        let id = usize::try_from(id.ok_or("generated dictionary id is null")?).map_err(|_| "generated dictionary id does not fit usize")?;
        if id >= 1024 { return Err("generated dictionary id is outside table".into()); }
        let value = Some(i128::from(session.read_i64(FieldId(1), id)?)); visitor(session, value, span_start, span_end)
    })
}

